import React from 'react'
import { styleOf } from '@/lib/qpu-style'
/** The stream of an address: the frames the block's own --qpu-frames gradient holds, stepped through at the vortex period (36 frames of 108 ms). A device reads it by streaming: verify { scan: samples }. */
export const QpuScan: React.FC<{ uuid: string; phase?: number; label?: string }> = ({ uuid, phase, label }) => (
  <div className="qpu-scan" role="img" aria-label={label ?? 'a scannable stream: one character a frame'} data-phase={phase === undefined ? undefined : ''} style={{ ...styleOf(uuid), ...(phase === undefined ? {} : { ['--qpu-phase' as string]: String(Math.floor(phase)) }), borderRadius: 'var(--radius, 0.432rem)', minHeight: '3em' }} />
)
